<?php

declare(strict_types=1);

namespace MarceloEatWorld\FalAI\Data;

/**
 * Lifecycle preference for files generated by a request or uploaded to the
 * fal.ai CDN: how long they are kept and who may read them.
 *
 * Serialized into the X-Fal-Object-Lifecycle-Preference header.
 */
final readonly class ObjectLifecycle
{
    /**
     * @param int|null $expirationSeconds Seconds before the file expires, null keeps it forever
     * @param array{default: string, rules?: list<array{user: string, decision: string}>}|null $initialAcl
     *        Initial access control: "default" is "allow", "forbid" or "hide", with optional
     *        per-user overrides ("user" is a fal.ai nickname)
     */
    public function __construct(
        public ?int $expirationSeconds = null,
        public ?array $initialAcl = null,
    ) {}

    public static function expiresIn(int $seconds): self
    {
        return new self(expirationSeconds: $seconds);
    }

    /**
     * Files readable only by the owner (and the users listed in $allow).
     *
     * @param list<string> $allow fal.ai nicknames granted read access
     */
    public static function private(array $allow = [], ?int $expirationSeconds = null): self
    {
        return new self(
            expirationSeconds: $expirationSeconds,
            initialAcl: [
                'default' => 'forbid',
                'rules' => array_map(
                    fn (string $user): array => ['user' => $user, 'decision' => 'allow'],
                    $allow,
                ),
            ],
        );
    }

    public function toArray(): array
    {
        $data = [];

        if ($this->expirationSeconds !== null) {
            $data['expiration_duration_seconds'] = $this->expirationSeconds;
        }

        if ($this->initialAcl !== null) {
            $data['initial_acl'] = $this->initialAcl;
        }

        return $data;
    }

    public function toHeader(): string
    {
        return json_encode($this->toArray(), JSON_THROW_ON_ERROR);
    }
}
